CREATE OR REPLACE FUNCTION public.conc_bank_batches(p_bank uuid) RETURNS TABLE(source text,entry_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
WITH bank AS (SELECT * FROM public.conc_bank_entries WHERE id=p_bank AND (auth.uid() IS NULL OR (public.can_access_conciliacao(auth.uid()) AND public.can_view_hotel_data(auth.uid(),hotel_id))))
SELECT 'rede'::text,r.id FROM bank b JOIN public.conc_rede_recebidos r ON r.hotel_id=b.hotel_id WHERE (r.matched_bank_id=b.id OR (b.description ILIKE 'RECEBIMENTO REDE%' AND r.matched_bank_id IS NULL AND b.line_date BETWEEN r.data-1 AND r.data+3 AND round(b.amount,2)=round(r.valor_depositado,2) AND upper(b.description) LIKE '%'||CASE upper(public.unaccent_safe(r.bandeira)) WHEN 'MASTERCARD' THEN 'MAST' WHEN 'AMERICAN EXPRESS' THEN 'AMEX' ELSE upper(public.unaccent_safe(r.bandeira)) END||'%' AND upper(b.description) ~ (' ('||CASE upper(public.unaccent_safe(r.modalidade)) WHEN 'CREDITO' THEN 'CD|AT' WHEN 'DEBITO' THEN 'DB' WHEN 'ANTECIPADO' THEN 'AT' ELSE 'INVALID' END||')[0-9]')))
UNION ALL SELECT 'b2b',d.id FROM bank b JOIN public.conc_b2b_receipts d ON d.hotel_id=b.hotel_id AND d.tipo_lancamento='deposit' WHERE (d.matched_bank_id=b.id OR (b.description ILIKE 'ZOOP%' AND d.matched_bank_id IS NULL AND b.line_date BETWEEN d.data_operacao-5 AND d.data_operacao+10 AND round(b.amount,2)=round(abs(d.valor_recebivel_liquido),2)));
$$;
GRANT EXECUTE ON FUNCTION public.conc_batch_summary(text,uuid),public.conc_batch_rows(text,uuid),public.conc_bank_batches(uuid) TO supabase_read_only_user;
COMMENT ON FUNCTION public.conc_batch_rows(text,uuid) IS 'Private lineage resolver; no anonymous or authenticated direct grant. Authorized detail RPC gates hotel access; read-only diagnostic role may inspect.';